// SCOPE:plugin — the generated list of units that mount themselves.
//
// `Capability.Register` is where a unit opts into building itself at boot. The
// list in internal/server/units.gen.go is generated from it, and these three
// tests are what keep the pair honest:
//
//   - the generated file matches the registry (no hand edit survives a build);
//   - the named package really exports the seam's `Register` signature, so a
//     typo is a test failure rather than a link error in someone's tree;
//   - the composition root does not import the unit it no longer builds, which
//     is the whole point: the root holding a constructor is what made units
//     unremovable.
//
// Regenerate with:
//
//	go test ./internal/capabilities/ -run TestBundledUnitRegistrationIsCurrent -update
package capabilities

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"testing"
)

// unitsGenPath is the generated file buildChiMux's recipe step calls.
const unitsGenPath = "internal/server/units.gen.go"

// recipeImport and registerImport are the two package paths the seam's
// signature names; the signature check resolves aliases to these, so a unit may
// import them under any name.
const (
	recipeImport   = "github.com/calionauta/gogogo/internal/recipe"
	registerImport = "github.com/calionauta/gogogo/internal/recipe/register"
)

// TestBundledUnitRegistrationIsCurrent pins internal/server/units.gen.go to the
// registry. A unit that sets Register without regenerating fails here, which is
// the same contract the templ and docs generators keep.
func TestBundledUnitRegistrationIsCurrent(t *testing.T) {
	root := repoRoot(t)
	path := filepath.Join(root, filepath.FromSlash(unitsGenPath))
	want := renderBundledUnits(t, root)
	if *apiRoutesDocUpdate {
		if err := os.WriteFile(path, want, 0o600); err != nil {
			t.Fatalf("write %s: %v", unitsGenPath, err)
		}
		return
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v (regenerate with -update)", unitsGenPath, err)
	}
	if !bytes.Equal(raw, want) {
		t.Fatalf("%s is stale: the registry and the generated list disagree.\n"+
			"Regenerate with:\n  go test ./internal/capabilities/ -run TestBundledUnitRegistrationIsCurrent -update",
			unitsGenPath)
	}
}

// mountEntry is one self-mounting unit as the generated file needs it.
type mountEntry struct {
	id    string
	alias string
	path  string
}

// mountEntries reads the registry into import entries. Order is by id, so the
// generated file diffs cleanly when a unit is added.
func mountEntries(t *testing.T, root string) []mountEntry {
	t.Helper()
	module := testModulePath(t, root)
	var entries []mountEntry
	for _, c := range All {
		if c.Register == "" {
			continue
		}
		entries = append(entries, mountEntry{
			id:    c.ID,
			alias: mountAlias(c.Register),
			path:  module + "/" + strings.TrimPrefix(c.Register, "./"),
		})
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].id < entries[j].id })
	return entries
}

// mountAlias is the Go identifier for one unit's package: the last two path
// segments joined, because a unit's register package is named `handlers` and
// that alone would collide across units.
func mountAlias(registerPath string) string {
	parts := strings.Split(strings.Trim(registerPath, "/"), "/")
	tail := parts[len(parts)-1]
	if len(parts) > 1 {
		tail = parts[len(parts)-2] + tail
	}
	var b strings.Builder
	for _, r := range tail {
		if r == '_' || (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') {
			b.WriteRune(r)
		}
	}
	return b.String()
}

// renderBundledUnits is the whole generated file.
func renderBundledUnits(t *testing.T, root string) []byte {
	t.Helper()
	entries := mountEntries(t, root)

	var b strings.Builder
	b.WriteString("// Code generated by TestBundledUnitRegistrationIsCurrent in internal/capabilities. DO NOT EDIT.\n\n")
	b.WriteString("package server\n\n")
	b.WriteString("import (\n")
	for _, e := range entries {
		fmt.Fprintf(&b, "\t%s %q\n", e.alias, e.path)
	}
	if len(entries) > 0 {
		b.WriteString("\n")
	}
	fmt.Fprintf(&b, "\t%q\n", recipeImport)
	fmt.Fprintf(&b, "\t%q\n", registerImport)
	b.WriteString(")\n\n")
	b.WriteString("// bundledUnits is every in-tree unit that mounts itself, in id order. The list\n")
	b.WriteString("// is generated from `capabilities.Capability.Register`, so a unit opts in by\n")
	b.WriteString("// naming its package in the registry — the file that already owns its identity.\n")
	b.WriteString("var bundledUnits = []register.Func{\n")
	for _, e := range entries {
		fmt.Fprintf(&b, "\t%s.Register,\n", e.alias)
	}
	b.WriteString("}\n\n")
	b.WriteString("// registerBundledUnits is the one generated call the composition root makes for\n")
	b.WriteString("// the tree's own units. It is separate from registerInstalledRecipes because the\n")
	b.WriteString("// two sets have different lifetimes: an installed recipe can be uninstalled, a\n")
	b.WriteString("// unit of this tree is removed by deleting its files and regenerating.\n")
	b.WriteString("func registerBundledUnits(reg *recipe.Registry, d register.Deps) {\n")
	b.WriteString("\tfor _, registerUnit := range bundledUnits {\n")
	b.WriteString("\t\tregisterUnit(reg, d)\n")
	b.WriteString("\t}\n")
	b.WriteString("}\n")

	formatted, err := format.Source([]byte(b.String()))
	if err != nil {
		t.Fatalf("the generated registration does not parse: %v", err)
	}
	return formatted
}

// TestSelfMountingUnitsExportRegister checks the promise `Register` makes. It
// parses the named package instead of importing it: the registry is data, and a
// test that had to link twelve units to read it would pay the app's whole
// dependency graph for a signature check.
func TestSelfMountingUnitsExportRegister(t *testing.T) {
	root := repoRoot(t)
	checked := 0
	for _, c := range All {
		if c.Register == "" {
			continue
		}
		checked++
		if !packageDeclaresRegister(t, root, c) {
			t.Errorf("%s sets Register=%q, but that package declares no "+
				"`func Register(reg *recipe.Registry, d register.Deps)`",
				c.ID, c.Register)
		}
	}
	if checked == 0 {
		t.Fatal("no capability sets Register: the self-mounting path is untested and would rot silently")
	}
}

// packageDeclaresRegister parses the unit's package and looks for the exported
// Register with the seam's exact parameter list.
func packageDeclaresRegister(t *testing.T, root string, c Capability) bool {
	t.Helper()
	dir := filepath.Join(root, filepath.FromSlash(c.Register))
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Errorf("%s: read %s: %v", c.ID, c.Register, err)
		return false
	}
	fset := token.NewFileSet()
	for _, entry := range entries {
		name := entry.Name()
		if entry.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		file, perr := parser.ParseFile(fset, filepath.Join(dir, name), nil, 0)
		if perr != nil {
			t.Errorf("%s: parse %s/%s: %v", c.ID, c.Register, name, perr)
			return false
		}
		if declaresSeamRegister(file) {
			return true
		}
	}
	return false
}

// declaresSeamRegister reports whether file declares
// `func Register(reg *recipe.Registry, d register.Deps)`.
func declaresSeamRegister(file *ast.File) bool {
	imports := importAliases(file)
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Name.Name != "Register" || fn.Recv != nil {
			continue
		}
		params := fn.Type.Params.List
		if len(params) != 2 || len(params[0].Names) == 0 || len(params[1].Names) == 0 {
			continue
		}
		star, ok := params[0].Type.(*ast.StarExpr)
		if !ok {
			continue
		}
		first, ok := star.X.(*ast.SelectorExpr)
		if !ok || first.Sel.Name != "Registry" || qualifierPath(first.X, imports) != recipeImport {
			continue
		}
		second, ok := params[1].Type.(*ast.SelectorExpr)
		if !ok || second.Sel.Name != "Deps" || qualifierPath(second.X, imports) != registerImport {
			continue
		}
		return true
	}
	return false
}

// importAliases maps the names a file gives its imports to their paths, so the
// signature check does not depend on what a unit calls the seam's packages.
func importAliases(file *ast.File) map[string]string {
	out := map[string]string{}
	for _, spec := range file.Imports {
		path := strings.Trim(spec.Path.Value, `"`)
		name := path[strings.LastIndex(path, "/")+1:]
		if spec.Name != nil {
			name = spec.Name.Name
		}
		out[name] = path
	}
	return out
}

// qualifierPath resolves the package part of `pkg.Name` to its import path.
func qualifierPath(expr ast.Expr, imports map[string]string) string {
	ident, ok := expr.(*ast.Ident)
	if !ok {
		return ""
	}
	return imports[ident.Name]
}

// TestCompositionRootDoesNotConstructSelfMountingUnits is the invariant that
// makes a unit removable: once it mounts itself, the root must not import it.
// The generated list is the one exception, because it is the mount.
func TestCompositionRootDoesNotConstructSelfMountingUnits(t *testing.T) {
	root := repoRoot(t)
	module := testModulePath(t, root)
	owners := map[string]string{}
	for _, c := range All {
		if c.Register != "" {
			owners[module+"/"+strings.TrimPrefix(c.Register, "./")] = c.ID
		}
	}
	if len(owners) == 0 {
		t.Fatal("no capability sets Register: the composition-root gate would pass vacuously")
	}

	dir := filepath.Join(root, "internal", "server")
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatalf("read internal/server: %v", err)
	}
	for _, entry := range entries {
		name := entry.Name()
		if entry.IsDir() || !strings.HasSuffix(name, ".go") ||
			strings.HasSuffix(name, "_test.go") || name == filepath.Base(unitsGenPath) {
			continue
		}
		file, perr := parser.ParseFile(token.NewFileSet(), filepath.Join(dir, name), nil, parser.ImportsOnly)
		if perr != nil {
			t.Fatalf("parse %s: %v", name, perr)
		}
		for _, spec := range file.Imports {
			path := strings.Trim(spec.Path.Value, `"`)
			if unit, ok := owners[path]; ok {
				t.Errorf("internal/server/%s imports %s, which mounts itself: "+
					"the composition root must not construct a unit that Capability.Register names",
					name, unit)
			}
		}
	}
}

// testModulePath reads the tree's module path, the prefix every generated
// import needs (and the one a renamed project has).
func testModulePath(t *testing.T, root string) string {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(root, "go.mod"))
	if err != nil {
		t.Fatalf("read go.mod: %v", err)
	}
	for line := range strings.SplitSeq(string(raw), "\n") {
		if rest, ok := strings.CutPrefix(strings.TrimSpace(line), "module "); ok {
			if mod := strings.TrimSpace(rest); mod != "" {
				return mod
			}
		}
	}
	t.Fatal("go.mod has no module line")
	return ""
}
